Thumbnail HTML qurish.kod:
var inp=$("Kirish tayyorlash").item.json;
var spec={};try{spec=$("Thumbnail spetsifikatsiyasi").item.json||{};}catch(e){}
var avatarUrl=($json.data&&$json.data.image_url)||($json.image_url)||"";
var raqam=spec.yt_matn||inp.burchak;
var raqamWords=raqam.split(new RegExp("\\s+","g")).filter(function(w){return w.length>0;});
if(raqamWords.length>4)raqam=raqamWords.slice(0,4).join(" ");
var sar=inp.yt_sarlavha;
var taqiqlar=String(spec.taqiq||"").split(",").map(function(t){return t.trim().toLowerCase();});
// T1 yoki "yuz yoq" taqiq bo'lsa avatar ko'rsatilmaydi
var showFace=inp.mavzu_kod!=="T1"&&taqiqlar.indexOf("yuz yoq")<0;
var asosiyRang=spec.rang||"#D6AD62";
var ab_matn=spec.ab_matn||raqamWords.slice(0,2).join(" ");
function buildHtml(customMatn){
  var avatarPart=showFace&&avatarUrl?"<div style='width:50%;height:100%;position:relative;overflow:hidden;'><img src='"+avatarUrl+"' style='width:100%;height:100%;object-fit:cover;object-position:top;'><div style='position:absolute;top:0;right:0;bottom:0;width:60%;background:linear-gradient(to right,transparent,#0A1727);'></div></div>":"";
  var rightW=showFace&&avatarUrl?"50%":"100%";
  var pad=showFace&&avatarUrl?"60px 80px":"60px 120px";
  return "<!DOCTYPE html><html><head><meta charset='UTF-8'><link rel='stylesheet' href='https://fonts.googleapis.com/css2?family=Sora:wght@700&display=block'></head><body style='margin:0;padding:0;width:1280px;height:720px;overflow:hidden;background:#0A1727;display:flex;align-items:center;font-family:Sora,sans-serif;'>"+avatarPart+"<div style='width:"+rightW+";padding:"+pad+";display:flex;flex-direction:column;justify-content:center;gap:30px;'><div style='font-size:160px;font-weight:700;color:"+asosiyRang+";line-height:1;'>"+customMatn+"</div><div style='font-size:52px;font-weight:700;color:#F7F5F0;'>"+sar.split(new RegExp("\\s+","g")).slice(0,5).join(" ")+"</div><div style='font-size:24px;color:rgba(247,245,240,.5);'>@zibrock_turkiye</div></div></body></html>";
}
return{json:{htmls:[{variant:"asosiy",html:buildHtml(raqam)},{variant:"ab",html:buildHtml(ab_matn)}],job_id:inp.job_id,burchak:inp.burchak,yt_sarlavha:inp.yt_sarlavha}};
